BEGIN;
CREATE TABLE IF NOT EXISTS app_users (
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 name varchar(100) NOT NULL,email varchar(254) NOT NULL UNIQUE,password_hash text NOT NULL,
 role text NOT NULL DEFAULT 'buyer' CHECK(role IN ('buyer','moderator','admin','super_admin')),
 verified boolean NOT NULL DEFAULT false,suspended boolean NOT NULL DEFAULT false,
 mfa_secret text,mfa_enabled boolean NOT NULL DEFAULT false,last_otp_step bigint NOT NULL DEFAULT -1,
 preferences jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS app_sessions (sid varchar PRIMARY KEY,sess json NOT NULL,expire timestamp(6) NOT NULL);
CREATE INDEX IF NOT EXISTS app_sessions_expire_idx ON app_sessions(expire);
CREATE TABLE IF NOT EXISTS app_tokens (token_hash text PRIMARY KEY,user_id int NOT NULL REFERENCES app_users(id),kind text NOT NULL,expires_at timestamptz NOT NULL);
ALTER TABLE sellers ADD COLUMN IF NOT EXISTS slug text;
ALTER TABLE sellers ADD COLUMN IF NOT EXISTS is_approved boolean NOT NULL DEFAULT true;
CREATE UNIQUE INDEX IF NOT EXISTS sellers_slug_idx ON sellers(slug);
ALTER TABLE sellers ADD COLUMN IF NOT EXISTS operating_state text NOT NULL DEFAULT 'active' CHECK(operating_state IN ('active','paused','suspended'));
ALTER TABLE sellers ADD COLUMN IF NOT EXISTS appearance jsonb NOT NULL DEFAULT '{}';
ALTER TABLE sellers ADD COLUMN IF NOT EXISTS draft_appearance jsonb NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS shop_members (shop_id int REFERENCES sellers(id),user_id int REFERENCES app_users(id),owner boolean NOT NULL DEFAULT false,permissions jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(shop_id,user_id));
CREATE TABLE IF NOT EXISTS seller_applications (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id int NOT NULL UNIQUE REFERENCES app_users(id),shop_id int REFERENCES sellers(id),data jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted','under_review','changes_requested','approved','rejected')),feedback text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS product_drafts (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shop_id int NOT NULL REFERENCES sellers(id),data jsonb NOT NULL DEFAULT '{}',state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','submitted','changes_requested','approved','rejected','archived')),feedback text NOT NULL DEFAULT '',version int NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE categories ADD COLUMN IF NOT EXISTS parent_id int REFERENCES categories(id);
ALTER TABLE categories ADD COLUMN IF NOT EXISTS attributes jsonb NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS media_urls jsonb NOT NULL DEFAULT '[]';
ALTER TABLE products ADD COLUMN IF NOT EXISTS specifications text NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN IF NOT EXISTS category_attributes jsonb NOT NULL DEFAULT '{}';
ALTER TABLE products ADD COLUMN IF NOT EXISTS draft_id int REFERENCES product_drafts(id);
ALTER TABLE products ADD COLUMN IF NOT EXISTS variant_sku text;
ALTER TABLE products ADD COLUMN IF NOT EXISTS media_url text;
CREATE UNIQUE INDEX IF NOT EXISTS products_shop_sku_idx ON products(seller_id,variant_sku) WHERE variant_sku IS NOT NULL;
ALTER TABLE checkout_requests ADD COLUMN IF NOT EXISTS buyer_user_id int REFERENCES app_users(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS buyer_user_id int REFERENCES app_users(id);
CREATE INDEX IF NOT EXISTS orders_buyer_user_idx ON orders(buyer_user_id);
CREATE TABLE IF NOT EXISTS app_notifications (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id int NOT NULL REFERENCES app_users(id),message text NOT NULL,href text NOT NULL DEFAULT '/',seen boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id int REFERENCES app_users(id),action text NOT NULL,resource text NOT NULL,reason text NOT NULL DEFAULT '',details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shop_invitations (id uuid PRIMARY KEY,email text NOT NULL,shop_id int NOT NULL REFERENCES sellers(id),permissions jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days');
CREATE TABLE IF NOT EXISTS user_saved (user_id int REFERENCES app_users(id),product_id int REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS user_reports (id int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id int REFERENCES app_users(id),message text NOT NULL,state text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_settings (key text PRIMARY KEY,value jsonb NOT NULL);
INSERT INTO platform_settings VALUES('marketplace','{"name":"Savdo","currency":"UZS","checkout":"Demo cash on delivery"}') ON CONFLICT DO NOTHING;
COMMIT;
